select 
  from sdsshop.u_m_buyer2
 where shop_code = #{query.shopCode}
   and buyercode = #{query.buyerCode}

  and buyer2name like concat('%', #{query.buyer2Name}, '%')

  and buyer2user like concat('%', #{query.buyer2User}, '%')

  and mobile like concat('%', #{query.mobile}, '%')

  and activeflag = #{query.activeFlag}
 order by activeflag desc, createtime desc, buyer2code desc

